// Independent XMLDSig oracle using only the JDK's JSR 105 implementation.
// All external URIs are mapped explicitly to local fixtures. There is no fallback
// to HTTP/file URI dereferencing. Private keys are generated by the harness.
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.security.spec.*;
import java.util.*;
import javax.xml.XMLConstants;
import javax.xml.crypto.*;
import javax.xml.crypto.dom.*;
import javax.xml.crypto.dsig.*;
import javax.xml.crypto.dsig.dom.*;
import javax.xml.crypto.dsig.spec.*;
import javax.xml.parsers.*;
import javax.xml.transform.*;
import javax.xml.transform.dom.*;
import javax.xml.transform.stream.*;
import org.w3c.dom.*;

public class DetachedOracle {
    static byte[] pem(Path path) throws Exception {
        String text = Files.readString(path, StandardCharsets.US_ASCII)
            .replaceAll("-----BEGIN [^-]+-----", "")
            .replaceAll("-----END [^-]+-----", "").replaceAll("\\s", "");
        return Base64.getDecoder().decode(text);
    }
    static Key key(Path path, boolean privateKey) throws Exception {
        byte[] der = pem(path);
        for (String algorithm : List.of("RSA", "EC")) {
            try {
                KeyFactory f = KeyFactory.getInstance(algorithm);
                return privateKey ? f.generatePrivate(new PKCS8EncodedKeySpec(der))
                                  : f.generatePublic(new X509EncodedKeySpec(der));
            } catch (GeneralSecurityException ignored) { }
        }
        throw new GeneralSecurityException("unsupported PEM key");
    }
    static DocumentBuilder builder() throws Exception {
        DocumentBuilderFactory f = DocumentBuilderFactory.newInstance();
        f.setNamespaceAware(true); f.setXIncludeAware(false);
        f.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        f.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        f.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
        return f.newDocumentBuilder();
    }
    static URIDereferencer resolver(Map<String,Path> resources) {
        return (reference, context) -> {
            Path path = resources.get(reference.getURI());
            if (path == null) throw new URIReferenceException("URI not in fixture allowlist");
            try { return new OctetStreamData(new ByteArrayInputStream(Files.readAllBytes(path)), reference.getURI(), null); }
            catch (IOException ex) { throw new URIReferenceException(ex); }
        };
    }
    public static void main(String[] args) throws Exception {
        if (args.length < 4) throw new IllegalArgumentException("mode key xml ...");
        String mode = args[0];
        XMLSignatureFactory f = XMLSignatureFactory.getInstance("DOM");
        if (mode.equals("sign") || mode.equals("sign-bad-second")) {
            // mode private.pem output.xml CM SIGMETHOD (URI PATH DIGEST TRANSFORMS)*
            if ((args.length - 5) % 4 != 0) throw new IllegalArgumentException("reference arguments");
            Document doc = builder().newDocument();
            List<Reference> refs = new ArrayList<>();
            Map<String,Path> resources = new LinkedHashMap<>();
            for (int i=5; i<args.length; i+=4) {
                String uri = args[i]; resources.put(uri, Path.of(args[i+1]));
                DigestMethod digest = f.newDigestMethod(args[i+2], null);
                List<Transform> transforms = new ArrayList<>();
                if (!args[i+3].equals("-")) {
                    for (String algorithm : args[i+3].split("\\|")) {
                        transforms.add(f.newTransform(algorithm, (TransformParameterSpec)null));
                    }
                }
                if (mode.equals("sign-bad-second") && refs.size()==1) {
                    int size = args[i+2].endsWith("sha512") ? 64 : args[i+2].endsWith("sha384") ? 48 : 32;
                    refs.add(f.newReference(uri, digest, transforms, null, null, new byte[size]));
                } else refs.add(f.newReference(uri, digest, transforms, null, null));
            }
            SignedInfo si = f.newSignedInfo(f.newCanonicalizationMethod(args[3], (C14NMethodParameterSpec)null),
                f.newSignatureMethod(args[4], null), refs);
            DOMSignContext context = new DOMSignContext(key(Path.of(args[1]), true), doc);
            context.setDefaultNamespacePrefix("ds"); context.setURIDereferencer(resolver(resources));
            context.setProperty("org.jcp.xml.dsig.secureValidation", Boolean.TRUE);
            f.newXMLSignature(si, null).sign(context);
            TransformerFactory tf = TransformerFactory.newInstance();
            tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
            Transformer t = tf.newTransformer(); t.setOutputProperty(OutputKeys.INDENT, "no");
            t.transform(new DOMSource(doc), new StreamResult(Path.of(args[2]).toFile()));
            System.out.println("signed");
        } else if (mode.equals("verify")) {
            // mode public.pem signature.xml (URI PATH)*
            if ((args.length - 3) % 2 != 0) throw new IllegalArgumentException("resource arguments");
            Map<String,Path> resources = new LinkedHashMap<>();
            for (int i=3; i<args.length; i+=2) resources.put(args[i], Path.of(args[i+1]));
            Document doc = builder().parse(Path.of(args[2]).toFile());
            Element root = doc.getDocumentElement();
            if (!XMLSignature.XMLNS.equals(root.getNamespaceURI()) || !"Signature".equals(root.getLocalName()))
                throw new IllegalArgumentException("standalone Signature required");
            DOMValidateContext context = new DOMValidateContext(key(Path.of(args[1]), false), root);
            context.setURIDereferencer(resolver(resources));
            context.setProperty("org.jcp.xml.dsig.secureValidation", Boolean.TRUE);
            XMLSignature signature = f.unmarshalXMLSignature(context);
            boolean sv = signature.getSignatureValue().validate(context);
            List<Boolean> digests = new ArrayList<>();
            for (Reference reference : signature.getSignedInfo().getReferences()) digests.add(reference.validate(context));
            boolean core = signature.validate(context);
            System.out.println("{\"signature_value\":"+sv+",\"references\":"+digests+",\"core\":"+core+"}");
        } else throw new IllegalArgumentException("unsupported mode");
    }
}
